(window.LADDER_CARDS=window.LADDER_CARDS||{})["2a"]=[{"q": "On rung 2, what is a row?", "a": "a line, one under another", "w": ["a single letter of a line", "a table of every case", "a note kept in the margin"], "why": "2a1: a row is a line."}, {"q": "A given says several things at once and is written over several rows. What has been added?", "a": "nothing: its aspects are written out", "w": ["a new fact the given lacked", "a case set in from the margin", "a ⊥ that closes the given"], "why": "2a2: aspects of the givens."}, {"q": "Under the givens, what may a new row be?", "a": "the result of a technique on rows above it", "w": ["any true statement", "a guess", "a row copied from another case"], "why": "2a3: results keep the truth."}, {"q": "A stack of rows. What does it say?", "a": "all of its rows, as one row of ands", "w": ["only its last row", "any one of its rows", "its first row"], "why": "2a4: rows and ∧ are two layouts of one claim."}, {"q": "A row holds an or. How are its options worked?", "a": "each as a case, set in from the margin", "w": ["split into two margin rows", "kept in one row", "by dropping one option"], "why": "2a5: cases are set in."}, {"q": "Inside one case, which rows may be used?", "a": "its own rows and the margin rows above", "w": ["the rows of any other case", "only the givens, nothing else", "only its own rows, no givens"], "why": "Never another case’s rows."}, {"q": "A case reaches ⊥. What becomes of it?", "a": "it is closed", "w": ["it is the answer", "it is moved to the margin", "it is rubbed out"], "why": "2a7: a case that cannot stand."}, {"q": "When may a row come back to the margin from cases?", "a": "when every case of the or reaches it", "w": ["when one case reaches it", "when the first case reaches it", "never"], "why": "2a8: back to the margin."}];
