(window.LADDER_CARDS=window.LADDER_CARDS||{})["2k"]=[{"q": "A set is made by a condition. What does every member get?", "a": "that condition: it is how it got in", "w": ["nothing until it is checked", "the size of the set", "the condition of another set"], "why": "2k1: grouped by a shared quality."}, {"q": "2e sifts the fliers out of a bowl of animals. What is true of each thing in the fliers?", "a": "it flies", "w": ["it is a bird", "it is the largest", "it is in the bowl alone"], "why": "Flying is how it got in."}, {"q": "Every bird in the cage is moved to the garden. This bird was in the cage. Where is it?", "a": "in the garden", "w": ["still in the cage", "in neither", "it cannot be said"], "why": "2k2: done to the whole, done to each."}, {"q": "Which rung 2 idea is at work when a step for any member is a step for all?", "a": "2b’s every", "w": ["2b’s some", "a case set in", "a count of members"], "why": "To speak of everything, speak of anything."}, {"q": "“The flock is large.” What does it say of each bird?", "a": "nothing: size belongs to the set", "w": ["each bird is large", "each bird is small", "each bird is in a large set, so large"], "why": "2k3: where it stops."}, {"q": "Which two does 2d keep apart for this reason?", "a": "“is in” and “is part of”", "w": ["“every” and “some”", "“and” and “or”", "“if” and “only if”"], "why": "A set’s size is not a member’s."}, {"q": "Carrying a property of the whole to its parts when it should not be carried. Its accepted name?", "a": "the fallacy of division", "w": ["the fallacy of composition", "the domain", "induction"], "why": "The opposite mistake is composition."}, {"q": "How many members does a set look at, to be right about each?", "a": "none of them", "w": ["every one, in turn", "one sample", "half of them"], "why": "The set that speaks for its members."}];
